#define FW_VERSION 1

_Static_assert(GB_ROM_BANKS >= 2 && GB_ROM_BANKS <= 16, "every bank is resident: 2-16 banks");

// Banks 0 and 1 are cartserve's own: cs_seed() lands in 0, and 1 is the VMU/art window.
static uint8_t __attribute__((aligned(0x4000))) g_banks[GB_ROM_BANKS > 2 ? GB_ROM_BANKS - 2 : 1][0x4000];
static uint8_t *g_bank_ptr[GB_ROM_BANKS];

// GB -> firmware: writes to $6000+n, n from A0-A2, latched for free by write_capture.
#define MBOX_REGION   0x6000
enum { MBOX_BTN = 0, MBOX_MODE = 1, MBOX_CFG_IDX = 2, MBOX_CFG_VAL = 3, MBOX_COMMIT = 4 };

// firmware -> GB: plain bytes of the served bank 0, rewritten under the console.
#define STATUS_ADDR    0x0010
#define VERSION_ADDR   0x0011
#define ID_ADDR        0x0012   // adapter slot from the cable ID ladder (ADAPT_*)
#define DIAG_ADDR      0x0013   // driver error code, so the ROM can say why nothing is driven
// The PROTO_SEL echo is no proof a driver started; these are what core1 owns and when it acted.
#define ACTIVE_ADDR    0x0014   // PROTO_* of the resident driver, PROTO_NONE if nothing is driven
#define APPLYSEQ_ADDR  0x0015   // low byte of the drv_apply() counter
// The Visual Memory. SEQ is bumped after a whole frame is in place, so the ROM never blits mid-write.
#define VMU_SEQ_ADDR   0x0016
#define VMU_STAT_ADDR  0x0017
#define VMU_SAVES_ADDR 0x0018
// The controller picture staged at $4600 (padart.h). PROTO says whose it is, SEQ that it is whole.
#define ART_SEQ_ADDR   0x0019
#define ART_PROTO_ADDR 0x001a
// pad.h's PAD_* bits 0-23 after map_apply(), low byte first: what core1 drives, not what the GB pressed.
#define PAD_LIVE_ADDR  0x001b
#define PAD_LIVE_SEQ   0x001e   // poked last; the three data bytes are separate pokes and can tear

#define VMU_ST_CARD    0x01     // a card is live
#define VMU_ST_DIRTY   0x02     // writes the flash copy does not have yet
#define VMU_ST_SAVING  0x04     // a writeback is in flight
#define VMU_ST_FRAME   0x08     // the console has drawn to the LCD this session
#define CFG_MIRROR     0x0200   // CFG_LEN bytes, config_map.h
#define CATALOG_ADDR   0x0300   // driver catalog, pad_catalog.h. Seeded once at boot, never rewritten.

#define ST_ALIVE       0x01     // firmware up and serving
#define ST_LINK_UP     0x02     // transport connected
#define ST_FORCE_CFG   0x80     // escape hatch: ROM must leave capture mode

enum { MODE_CONFIG = 0, MODE_CAPTURE = 1 };

static uint8_t  g_config[CFG_LEN];
static volatile uint8_t  g_buttons, g_mode, g_status = ST_ALIVE;
static volatile uint8_t  g_cfg_idx, g_cfg_class, g_adapter, g_diag, g_active, g_aseq;
static volatile bool     g_cfg_dirty, g_commit_req, g_btn_pending;
static volatile uint32_t g_btn_seq, g_wr_count, g_mbox_writes, g_gb_runs;
static uint32_t g_ps_size;


static void publish_status(void) { cs_poke(STATUS_ADDR, g_status); }

static uint8_t g_vmu_stat = VMU_ST_CARD, g_vmu_saves;

// On change, like ACTIVE/APPLYSEQ: the ROM polls these every pass and a poke costs a bus cycle.
static void publish_vmu(void) {
    const vmu_stage_t *s = vmu_stage();
    uint8_t st = (uint8_t)(VMU_ST_CARD
                 | (s->writes != s->saved_writes ? VMU_ST_DIRTY : 0)
                 | (vmu_store_busy() ? VMU_ST_SAVING : 0)
                 | (s->lcd_frames ? VMU_ST_FRAME : 0));

    if (st != g_vmu_stat)              { g_vmu_stat = st;  cs_poke(VMU_STAT_ADDR, st); }
    if ((uint8_t)s->saves != g_vmu_saves) {
        g_vmu_saves = (uint8_t)s->saves;
        cs_poke(VMU_SAVES_ADDR, g_vmu_saves);
    }
}

// On change only, like publish_vmu(): a poke costs a bus cycle and the ROM polls these every pass.
static uint32_t g_pad_live = 0xffffffffU;
static uint8_t  g_pad_live_seq;

static void publish_pad_live(void) {
    uint32_t b = drv_pad_live() & 0xffffffU;
    if (b == g_pad_live) { return; }
    for (unsigned i = 0; i < 3; i++) {
        if (((b ^ g_pad_live) >> (8 * i)) & 0xffU) {
            cs_poke((uint16_t)(PAD_LIVE_ADDR + i), (uint8_t)(b >> (8 * i)));
        }
    }
    g_pad_live = b;
    cs_poke(PAD_LIVE_SEQ, ++g_pad_live_seq);            // after the data, always
}

static void publish_config(void) {
    for (uint32_t i = 0; i < CFG_LEN; i++) { cs_poke(CFG_MIRROR + i, g_config[i]); }
}

// A known cable overrides the selected protocol in g_config itself, so the mirror tells the menu.
static bool cable_select(void) {
#ifdef BENCH_PROTO
    return false;
#else
    uint8_t p = cable_id_proto(g_adapter, g_config[CFG_PROTO_SEL]);
    if (p == g_config[CFG_PROTO_SEL]) { return false; }
    g_config[CFG_PROTO_SEL] = p;
    return true;
#endif
}

// Config lives in the last flash sector. Erasing it live stalls core0, never the SRAM serve path.
#define CFG_FLASH_OFF (PICO_FLASH_SIZE_BYTES - FLASH_SECTOR_SIZE)
#define CFG_MAGIC     0x43474243u
#define CFG_PAGE      (2 * FLASH_PAGE_SIZE)   // magic + CFG_LEN rounded up to a programmable multiple

static void config_load(void) {
    const uint8_t *p = (const uint8_t *)(XIP_BASE + CFG_FLASH_OFF);
    uint32_t magic;
    memcpy(&magic, p, sizeof magic);
    if (magic == CFG_MAGIC) {
        memcpy(g_config, p + 4, CFG_LEN);
    } else {
        memset(g_config, 0xff, CFG_LEN);
    }
}

// core0 only. The erase runs with only core0's interrupts masked, which is safe solely because the
// binary is copy_to_ram and core1 never touches flash, XIP or PSRAM (see pad_driver.h).
static void config_save(void) {
    hard_assert(get_core_num() == 0);
    static uint8_t page[CFG_PAGE];
    uint32_t magic = CFG_MAGIC;
    memset(page, 0xff, sizeof page);
    memcpy(page, &magic, sizeof magic);
    memcpy(page + 4, g_config, CFG_LEN);
    flash_burn(CFG_FLASH_OFF, FLASH_SECTOR_SIZE, page, CFG_PAGE);
}

// Every config change lands here: the menu's mirror, the Transfer Pak slot, then core1.
static void reconfig(uint8_t cls, uint32_t now) {
    publish_config();
    romstore_config(g_config);
    drv_config_changed(g_config, cls, now);
}

