static const char k_bench_keys[] = "dawsjknm";   // GB bit order: R L U D A B SELECT START
static uint8_t  g_inject;
static uint32_t g_inject_ms;
static uint8_t  g_bench_slot;   // bench 'g': the Transfer Pak slot the GB menu would have written

void snes_bench_force(uint32_t w, bool on);                     // drivers/snes.c, bench only
void gen_bench_force(uint32_t dpad, uint32_t tltr, bool on);    // drivers/genesis.c, bench only
void gen_bench_stats(uint32_t *polls, uint32_t *resyncs, uint32_t *drops);
